mapper.select:
SELECT * FROM tour_routes
WHERE deleted = 0

    AND (name LIKE CONCAT('%', #{keyword}, '%')
         OR description LIKE CONCAT('%', #{keyword}, '%'))


    AND difficulty = #{difficulty}




            AND days >= 3


            AND days = #{days}




    AND FIND_IN_SET(#{tag}, tags)


    AND status = #{status}

ORDER BY is_official DESC, sort_order ASC, created_at DESC
